## 3. Usage example

```csharp
using System;
using CustomCollections;

class Program
{
    static void Main()
    {
        var stack = new Stack<int>(capacity: 2);   // start with capacity 2

        // Push a few values – the internal array will resize automatically.
        stack.Push(10);
        stack.Push(20);
        stack.Push(30); // triggers a resize from 2 → 4

        Console.WriteLine($"Count = {stack.Count}, Capacity = {stack.Capacity}"); // 3, 4

        Console.WriteLine("Top element: " + stack.Peek()); // 30

        while (stack.Count > 0)
        {
            Console.WriteLine("Pop: " + stack.Pop());
        }

